const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initial={clients:[{id:'1',name:'Residência Oliveira'},{id:'2',name:'Loja Invictus'}],cameras:[{id:'1',name:'Portão principal',client:'1',scene:0},{id:'2',name:'Estacionamento',client:'1',scene:1},{id:'3',name:'Jardim lateral',client:'1',scene:2},{id:'4',name:'Entrada da loja',client:'2',scene:3}],events:[{id:'EV-001',camera:'1',title:'Pessoa em área restrita',priority:'Alta',rule:'Entrada na zona do portão fora do horário permitido.',time:'19:35',status:'Pendente',note:''},{id:'EV-002',camera:'2',title:'Permanência de veículo',priority:'Média',rule:'Permanência superior ao limite de tempo configurado.',time:'18:47',status:'Pendente',note:''},{id:'EV-003',camera:'3',title:'Animal na área externa',priority:'Baixa',rule:'Evento informativo. Nenhuma resposta automática.',time:'18:20',status:'Pendente',note:''}],brand:'INVICTUS'};
let state;try{state=JSON.parse(localStorage.getItem('invictus-monitor-v1'))||structuredClone(initial);if(!Array.isArray(state.cameras)||!Array.isArray(state.events)||!Array.isArray(state.clients))throw Error();}catch{state=structuredClone(initial)}
let page='painel',filter='',eventStatus='Todos';const images=['photo-1600596542815-ffad4c1539a9','photo-1503376780353-7e6692767b70','photo-1416879595882-3373a0480b5b','photo-1600607687920-4e2a09cf159d'];const nav=[['painel','▦','Painel'],['cameras','▣','Câmeras'],['ocorrencias','△','Ocorrências'],['clientes','♧','Clientes'],['relatorios','▤','Relatórios'],['configuracoes','⚙','Configurações']];
function persist(){try{localStorage.setItem('invictus-monitor-v1',JSON.stringify(state))}catch{toast('Armazenamento indisponível. Alterações duram apenas nesta sessão.')}}function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',4500)}
function clientName(id){return state.clients.find(c=>c.id===id)?.name||'Local removido'}function cameras(){let loc=$('#profile').value==='client'?'1':$('#location').value;return state.cameras.filter(c=>!loc||c.client===loc)}function events(){const ids=cameras().map(c=>c.id);return state.events.filter(e=>ids.includes(e.camera))}function badge(p){return `<span class="badge ${p==='Alta'?'high':p==='Média'?'medium':'low'}">${esc(p)}</span>`}function cameraName(id){return state.cameras.find(c=>c.id===id)?.name||'Câmera'}
function locations(){let old=$('#location').value;$('#location').innerHTML='<option value="">Todos os locais</option>'+state.clients.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('');$('#location').value=old;$('#location').disabled=$('#profile').value==='client'}
function cards(){return cameras().filter(c=>c.name.toLowerCase().includes(filter.toLowerCase())).map(c=>{let alert=events().find(e=>e.camera===c.id&&e.priority==='Alta'&&e.status!=='Finalizada');return `<button class="camera ${alert?'alert':''}" data-camera="${esc(c.id)}" aria-label="Abrir ${esc(c.name)}"><div class="scene" style="background-image:url(https://images.unsplash.com/${images[c.scene%4]}?auto=format&fit=crop&w=900&q=80)"></div><div class="camtop"><span class="tag ${alert?'eventtag':''}">${alert?'△ Evento em análise':'CÂMERA '+esc(c.id)}</span><span class="tag">IMAGEM ILUSTRATIVA</span></div>${alert?'<div class="detection"><span>Exemplo</span></div>':''}<div class="cambottom"><span>${esc(c.name)}</span><span>⛶</span></div></button>`}).join('')||'<div class="empty">Nenhuma câmera encontrada.</div>'}
function eventRows(){return events().slice(0,3).map(e=>`<div class="event" role="button" tabindex="0" data-event="${e.id}"><span class="eventicon">${e.priority==='Alta'?'♙':e.priority==='Média'?'▱':'♧'}</span><div><strong>${esc(e.title)}</strong><small>${esc(cameraName(e.camera))}<br>Exemplo · ${e.time} · ${e.status}</small></div>${badge(e.priority)}</div>`).join('')||'<p class="empty">Nenhuma ocorrência neste local.</p>'}
function dashboard(){const es=events(),pending=es.filter(e=>e.status!=='Finalizada');return `<div class="stats">${[['▣','Câmeras cadastradas',cameras().length,'Conexão real pendente'],['△','Ocorrências abertas',pending.length,'Eventos demonstrativos'],['♙','Prioridade alta',pending.filter(e=>e.priority==='Alta').length,'Revisão pelo operador'],['▥','Locais monitorados',new Set(cameras().map(c=>c.client)).size,'Ambiente de demonstração']].map(x=>`<div class="stat"><span class="symbol">${x[0]}</span><div><small>${x[1]}</small><strong>${x[2]}</strong><em>${x[3]}</em></div></div>`).join('')}</div><div class="columns"><div><div class="panel"><div class="panelhead"><div><h3>Câmeras em monitoramento</h3><small>Visão unificada dos locais selecionados</small></div><a class="textbtn" href="#cameras">Ver todas ↗</a></div><div class="cameras">${cards()}</div></div><div class="panel"><div class="panelhead"><h3>Ocorrência em destaque</h3>${badge(pending[0]?.priority||'Baixa')}</div>${pending[0]?`<div class="focus"><span class="eventicon">△</span><div><h3>${esc(pending[0].title)}</h3><p>${esc(cameraName(pending[0].camera))} · ${pending[0].time}</p><p>${esc(pending[0].rule)}</p></div><button class="primary" data-event="${pending[0].id}">Analisar ocorrência →</button></div>`:'<div class="empty">Todas as ocorrências deste local foram finalizadas.</div>'}</div></div><div class="sidepanels"><div class="panel"><div class="panelhead"><h3>Ocorrências recentes</h3><a href="#ocorrencias" class="textbtn">Ver todas</a></div>${eventRows()}</div><div class="panel"><div class="panelhead"><h3>Status do ambiente</h3></div><div class="status"><div>Interface <span>Disponível</span></div><div>Armazenamento <span>Local no navegador</span></div><div>Câmeras reais <span>Não conectadas</span></div><div>Análise por IA <span>Não integrada</span></div><div>Gravação / sirenes <span>Não integradas</span></div></div><div class="notice">As imagens e ocorrências são exemplos. Este módulo ainda não realiza vigilância ou envia alertas.</div></div></div></div>`}
function eventTable(){let list=events().filter(e=>(eventStatus==='Todos'||e.status===eventStatus)&&`${e.title} ${cameraName(e.camera)}`.toLowerCase().includes(filter.toLowerCase()));return `<div class="panel"><div class="panelhead"><h3>Gestão de ocorrências</h3><button data-export class="textbtn">Exportar CSV ↓</button></div><div class="listfilters"><input id="search" aria-label="Buscar ocorrência" placeholder="Buscar por evento ou câmera" value="${esc(filter)}"><select id="eventStatus" aria-label="Status">${['Todos','Pendente','Em análise','Finalizada'].map(s=>`<option ${s===eventStatus?'selected':''}>${s}</option>`).join('')}</select></div><div class="tablewrap"><table><thead><tr><th>OCORRÊNCIA</th><th>CÂMERA</th><th>PRIORIDADE</th><th>STATUS</th><th>AÇÃO</th></tr></thead><tbody>${list.map(e=>`<tr><td>${esc(e.title)}<small>${e.id} · ${e.time}</small></td><td>${esc(cameraName(e.camera))}</td><td>${badge(e.priority)}</td><td>${e.status}</td><td><button data-event="${e.id}">Analisar</button></td></tr>`).join('')}</tbody></table>${list.length?'':'<div class="empty">Nenhuma ocorrência encontrada.</div>'}</div></div>`}
function render(){page=location.hash.slice(1)||'painel';if(!nav.some(n=>n[0]===page))page='painel';if($('#profile').value==='client'&&page==='clientes')page='painel';$('#title').textContent=nav.find(n=>n[0]===page)[2];$('#nav').innerHTML=nav.filter(n=>$('#profile').value!=='client'||n[0]!=='clientes').map(n=>`<a href="#${n[0]}" class="${page===n[0]?'active':''}"><span>${n[1]}</span>${n[2]}</a>`).join('');let html='';if(page==='painel')html=dashboard();if(page==='cameras')html=`<div class="panel"><div class="panelhead"><h3>Câmeras cadastradas</h3><small>Selecione para consultar os detalhes</small></div><div class="listfilters"><input id="search" aria-label="Buscar câmera" placeholder="Buscar câmera" value="${esc(filter)}"></div><div class="cameras">${cards()}</div></div>`;if(page==='ocorrencias')html=eventTable();if(page==='clientes')html=`<div class="panel"><div class="panelhead"><h3>Clientes e locais</h3><button class="primary" id="addClient">＋ Novo cliente</button></div><div class="tablewrap"><table><thead><tr><th>CLIENTE / LOCAL</th><th>CÂMERAS</th><th>MODALIDADE</th></tr></thead><tbody>${state.clients.map(c=>`<tr><td>${esc(c.name)}</td><td>${state.cameras.filter(x=>x.client===c.id).length}</td><td>Cadastro demonstrativo</td></tr>`).join('')}</tbody></table></div></div>`;if(page==='relatorios')html=`<div class="panel"><div class="panelhead"><h3>Resumo de ocorrências do local selecionado</h3><button class="primary" data-export>Exportar CSV</button></div><div class="status">${['Pendente','Em análise','Finalizada'].map(s=>`<div>${s}<span>${events().filter(e=>e.status===s).length}</span></div>`).join('')}</div><div class="notice">Relatório dos dados demonstrativos armazenados neste navegador. Não representa uma operação real.</div></div>`;if(page==='configuracoes')html=`<div class="panel"><div class="panelhead"><h3>Configurações do módulo</h3></div><div class="settings"><p>A seleção Central / Cliente demonstra as interfaces. Controle de acesso e isolamento de dados serão implementados no servidor.</p><label>Nome exibido na marca<input id="brandName" maxlength="24" value="${esc(state.brand)}"></label><button class="primary" id="saveBrand">Salvar identidade</button><p>Próximas integrações: autenticação, conexão segura às câmeras, regras de eventos, gravações e licenciamento.</p></div></div>`;$('#content').innerHTML=html;document.querySelector('.brand>span:last-child').innerHTML=esc(state.brand)+'<small>Monitoramento Inteligente</small>';bind();}
function openModal(title,fields,save){$('#dialogtitle').textContent=title;$('#fields').innerHTML=fields;$('.dialogactions').style.display=save?'flex':'none';$('#form').onsubmit=e=>{e.preventDefault();if(save)save(new FormData($('#form')))};$('#dialog').showModal()}
function closeModal(){$('#dialog').close()}$('#close').onclick=$('#cancel').onclick=closeModal;
function addCamera(){const cs=$('#profile').value==='client'?state.clients.filter(c=>c.id==='1'):state.clients;openModal('Adicionar câmera',`<p>O cadastro organiza a câmera. A conexão de vídeo será habilitada no módulo de integração.</p><label>Nome da câmera<input name="name" required maxlength="60" placeholder="Ex.: Portão lateral"></label><label>Cliente / local<select name="client">${cs.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('')}</select></label>`,data=>{let name=data.get('name').trim();if(!name)return;state.cameras.push({id:crypto.randomUUID(),name,client:data.get('client'),scene:state.cameras.length%4});persist();closeModal();render();toast('Câmera cadastrada. Conexão real pendente.')})}
function eventModal(id){let e=events().find(x=>x.id===id);if(!e)return;openModal(e.id+' · Análise da ocorrência',`<p><strong>${esc(e.title)}</strong><br>${esc(cameraName(e.camera))} · ${e.time}<br>${esc(e.rule)}</p><div class="notice">Evento demonstrativo. A detecção deve ser confirmada pelo operador.</div><label>Status<select name="status">${['Pendente','Em análise','Finalizada'].map(s=>`<option ${s===e.status?'selected':''}>${s}</option>`).join('')}</select></label><label>Registro do operador<textarea name="note" maxlength="2000" rows="4" placeholder="Descreva a verificação e as providências">${esc(e.note)}</textarea></label>`,data=>{if(data.get('status')==='Finalizada'&&!data.get('note').trim()){toast('Registre a verificação antes de finalizar.');return}e.status=data.get('status');e.note=data.get('note').trim();persist();closeModal();render();toast('Ocorrência atualizada.')})}
function exportCSV(){const rows=[['ID','Ocorrência','Câmera','Prioridade','Status','Observação'],...events().map(e=>[e.id,e.title,cameraName(e.camera),e.priority,e.status,e.note])];const csv='\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v).replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"').join(';')).join('\r\n');let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='invictus-ocorrencias-demo.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function bind(){document.querySelectorAll('[data-event]').forEach(el=>{el.onclick=()=>eventModal(el.dataset.event);el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();el.click()}}});document.querySelectorAll('[data-camera]').forEach(el=>el.onclick=()=>{let c=cameras().find(x=>x.id===el.dataset.camera);openModal(c.name,`<div class="notice">Câmera cadastrada · conexão pendente</div><p>Local: ${esc(clientName(c.client))}</p><p>A imagem do painel é ilustrativa. A transmissão ao vivo, gravação e configuração segura do equipamento dependem do próximo módulo.</p>`,null)});document.querySelectorAll('[data-export]').forEach(el=>el.onclick=exportCSV);if($('#search'))$('#search').oninput=e=>{let pos=e.target.selectionStart;filter=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)};if($('#eventStatus'))$('#eventStatus').onchange=e=>{eventStatus=e.target.value;render()};if($('#addClient'))$('#addClient').onclick=()=>openModal('Novo cliente / local','<label>Nome<input name="name" required maxlength="80" placeholder="Nome do cliente ou estabelecimento"></label>',data=>{let name=data.get('name').trim();if(!name)return;state.clients.push({id:crypto.randomUUID(),name});persist();locations();closeModal();render();toast('Cliente cadastrado.')});if($('#saveBrand'))$('#saveBrand').onclick=()=>{let val=$('#brandName').value.trim();if(!val)return;state.brand=val;persist();render();toast('Identidade atualizada neste navegador.')};}
$('#addCamera').onclick=addCamera;$('#location').onchange=()=>{filter='';render()};$('#profile').onchange=()=>{locations();filter='';render()};$('#menu').onclick=()=>document.body.classList.toggle('menuopen');window.addEventListener('hashchange',()=>{filter='';document.body.classList.remove('menuopen');render()});function clock(){$('#clock').textContent=new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}clock();setInterval(clock,60000);locations();render();
